// Interface strings for the translated locales. Keys are the English text; a missing key falls back to English,
// so names like LeWM or torch_world.nn, and technical terms kept in English (world model, planner, dataset), need
// no entry. Pages are translated in docs/<locale>/; every page that is not
// gets an English copy with a note, generated by prepare.py (which keeps the note's wording).

export interface Locale {
  label: string
  lang: string
  description: string
  strings: Record<string, string>
  theme: {
    outline: string
    prev: string
    next: string
    appearance: string
    toLight: string
    toDark: string
    menu: string
    top: string
    language: string
    notFound: [title: string, quote: string, link: string]
    search: [button: string, noResults: string, select: string, navigate: string, close: string, reset: string, back: string, details: string]
  }
}

