export const ENGLISH_STRINGS: Record<string, string> = {
  tagline:
    'World models for PyTorch. Shared layers, objectives, planners and environments, so every model is short and easy to compare.'
}

/** Translate `text` for the locale at `key` ('root' for English), falling back to English. */
export function translate(key: string, text: string): string {
  return LOCALES[key]?.strings[text] ?? ENGLISH_STRINGS[text] ?? text
}
